SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

DECLARE
    v_n NUMBER;
    v_admin NUMBER;
    v_doctor NUMBER;
    v_blob BLOB;
    v_raw RAW(2000);
    PROCEDURE rol(p_nombre VARCHAR2) IS
    BEGIN
        INSERT INTO ROL(nombre) SELECT p_nombre FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM ROL WHERE nombre=p_nombre);
        SELECT COUNT(*) INTO v_n FROM ROL WHERE nombre=p_nombre AND estado='ACTIVO';
        IF v_n<>1 THEN RAISE_APPLICATION_ERROR(-20930,'Rol requerido inactivo: '||p_nombre); END IF;
    END;
    PROCEDURE parametro(p_nombre VARCHAR2,p_valor VARCHAR2) IS
    BEGIN
        INSERT INTO PARAMETRO_SISTEMA(nombre,valor,descripcion)
        SELECT p_nombre,p_valor,'Valor inicial para pruebas' FROM DUAL
        WHERE NOT EXISTS (SELECT 1 FROM PARAMETRO_SISTEMA WHERE nombre=p_nombre);
    END;
    PROCEDURE cuenta(p_user VARCHAR2,p_rol VARCHAR2,p_estado VARCHAR2 DEFAULT 'ACTIVO',p_intentos NUMBER DEFAULT 0) IS
    BEGIN
        INSERT INTO USUARIO(id_rol,username,correo,password_hash,estado,intentos_fallidos)
        SELECT id_rol,p_user,p_user||'@example.com','$2a$10$F73MH.M57EzqweWrk7KiCOzvB4z5HTXl7esrODcS5LxjttIftHEvO',p_estado,p_intentos
        FROM ROL WHERE nombre=p_rol;
    END;
    PROCEDURE documento(p_doctor NUMBER,p_tipo VARCHAR2,p_hex VARCHAR2,p_estado VARCHAR2) IS
    BEGIN
        v_raw:=HEXTORAW(p_hex);
        DBMS_LOB.CREATETEMPORARY(v_blob,TRUE);
        DBMS_LOB.WRITEAPPEND(v_blob,UTL_RAW.LENGTH(v_raw),v_raw);
        INSERT INTO DOCUMENTO_DOCTOR(id_doctor,tipo_documento,nombre_archivo,tipo_mime,archivo,estado,fecha_validacion,usuario_validacion)
        VALUES(p_doctor,p_tipo,'TEST_'||p_tipo||'.pdf','application/pdf',v_blob,p_estado,
            CASE WHEN p_estado='VALIDADO' THEN SYSTIMESTAMP END,
            CASE WHEN p_estado='VALIDADO' THEN v_admin END);
        DBMS_LOB.FREETEMPORARY(v_blob);
    END;
BEGIN
    IF USER<>'KARELY_BD2' OR SYS_CONTEXT('USERENV','CURRENT_SCHEMA')<>'KARELY_BD2' THEN
        RAISE_APPLICATION_ERROR(-20931,'Usar la conexion KARELY_BD2, no SYSTEM');
    END IF;
    SELECT (SELECT COUNT(*) FROM USUARIO WHERE username LIKE 'test.%' OR correo LIKE 'test.%@example.com')
         + (SELECT COUNT(*) FROM DOCTOR WHERE numero_documento IN ('99000001','99000002','99000003','99000004'))
         + (SELECT COUNT(*) FROM PACIENTE WHERE numero_documento IN ('99100001','99100002','99100003','99100004','99100005','99100006'))
         + (SELECT COUNT(*) FROM ESPECIALIDAD WHERE nombre LIKE 'TEST %')
         + (SELECT COUNT(*) FROM CONSULTORIO WHERE nombre LIKE 'TEST %') INTO v_n FROM DUAL;
    IF v_n>0 THEN RAISE_APPLICATION_ERROR(-20932,'Ya hay datos TEST o documentos reservados: no se sobrescribio nada'); END IF;
    rol('ADMINISTRADORA'); rol('RECEPCIONISTA'); rol('CAJERA'); rol('TESORERA'); rol('DOCTOR');
    parametro('COMISION_DOCTOR','60'); parametro('COMISION_GESTORA','40');
    parametro('BLOQUEO_MINUTOS','10'); parametro('SESION_MINUTOS','20');
    cuenta('test.admin','ADMINISTRADORA'); cuenta('test.recepcion','RECEPCIONISTA');
    cuenta('test.caja','CAJERA'); cuenta('test.tesoreria','TESORERA'); cuenta('test.doctor','DOCTOR');
    cuenta('test.inactivo','RECEPCIONISTA','INACTIVO');
    cuenta('test.bloqueado','RECEPCIONISTA','BLOQUEADO',5);
    SELECT id_usuario INTO v_admin FROM USUARIO WHERE username='test.admin';
    DBMS_SESSION.SET_IDENTIFIER(TO_CHAR(v_admin));
    INSERT INTO ESPECIALIDAD(nombre,precio_consulta) VALUES('TEST Medicina general',100);
    INSERT INTO ESPECIALIDAD(nombre,precio_consulta) VALUES('TEST Dermatologia',150);
    INSERT INTO ESPECIALIDAD(nombre,precio_consulta) VALUES('TEST Pediatria',120);
    INSERT INTO CONSULTORIO(nombre,ubicacion) VALUES('TEST Consultorio 1','Piso 1, datos ficticios');
    INSERT INTO CONSULTORIO(nombre,ubicacion) VALUES('TEST Consultorio 2','Piso 2, datos ficticios');
    FOR h IN 8..17 LOOP
        INSERT INTO FRANJA_HORARIA(hora_inicio,hora_fin)
        SELECT LPAD(h,2,'0')||':00',LPAD(h+1,2,'0')||':00' FROM DUAL
        WHERE NOT EXISTS(SELECT 1 FROM FRANJA_HORARIA WHERE hora_inicio=LPAD(h,2,'0')||':00' AND hora_fin=LPAD(h+1,2,'0')||':00');
    END LOOP;
    SELECT COUNT(*) INTO v_n FROM FRANJA_HORARIA
    WHERE hora_inicio IN ('08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00')
      AND hora_fin=TO_CHAR(TO_DATE(hora_inicio,'HH24:MI')+1/24,'HH24:MI') AND estado='ACTIVO';
    IF v_n<>10 THEN RAISE_APPLICATION_ERROR(-20934,'Se requieren diez franjas activas entre 08:00 y 18:00'); END IF;
    INSERT INTO DOCTOR(tipo_documento,numero_documento,nombres,apellidos,correo,telefono)
    VALUES('DNI','99000001','TEST Ana','Medico Habilitado','test.doctor@example.com','900000001') RETURNING id_doctor INTO v_doctor;
    documento(v_doctor,'DNI','','VALIDADO');
    documento(v_doctor,'TITULO','','VALIDADO');
    UPDATE DOCTOR SET estado_documentacion='COMPLETO',id_usuario=(SELECT id_usuario FROM USUARIO WHERE username='test.doctor') WHERE id_doctor=v_doctor;
    INSERT INTO DOCTOR_ESPECIALIDAD(id_doctor,id_especialidad)
    SELECT v_doctor,id_especialidad FROM ESPECIALIDAD WHERE nombre IN ('TEST Medicina general','TEST Dermatologia');
    INSERT INTO DOCTOR(tipo_documento,numero_documento,nombres,apellidos,correo,telefono)
    VALUES('DNI','99000002','TEST Luis','Pendiente Documentos','test.pendiente@example.com','900000002') RETURNING id_doctor INTO v_doctor;
    documento(v_doctor,'DNI','','PENDIENTE');
    documento(v_doctor,'TITULO','','PENDIENTE');
    INSERT INTO DOCTOR_ESPECIALIDAD(id_doctor,id_especialidad)
    SELECT v_doctor,id_especialidad FROM ESPECIALIDAD WHERE nombre='TEST Pediatria';
    INSERT INTO DOCTOR(tipo_documento,numero_documento,nombres,apellidos,correo)
    VALUES('DNI','99000003','TEST Maria','Sin Documentacion','test.sin.documentos@example.com');
    INSERT INTO DOCTOR(tipo_documento,numero_documento,nombres,apellidos,correo)
    VALUES('DNI','99000004','TEST Pedro','Documento Rechazado','test.rechazado@example.com') RETURNING id_doctor INTO v_doctor;
    documento(v_doctor,'DNI','','RECHAZADO');
    documento(v_doctor,'TITULO','','RECHAZADO');
    UPDATE DOCTOR SET estado_documentacion='RECHAZADO' WHERE id_doctor=v_doctor;
    FOR i IN 1..6 LOOP
        INSERT INTO PACIENTE(tipo_documento,numero_documento,nombres,apellidos,fecha_nacimiento,telefono,correo,direccion,estado)
        VALUES('DNI',TO_CHAR(99100000+i),'TEST Paciente '||i,'Demostracion',ADD_MONTHS(TRUNC(SYSDATE),-12*(20+i)),TO_CHAR(901000000+i),'test.paciente'||i||'@example.com','Direccion ficticia '||i,CASE WHEN i=6 THEN 'INACTIVO' ELSE 'ACTIVO' END);
    END LOOP;
    INSERT INTO DISPONIBILIDAD_DOCTOR(id_doctor,id_franja,fecha_turno,id_especialidad)
    SELECT d.id_doctor,f.id_franja,TRUNC(SYSDATE)+dias.n,e.id_especialidad
    FROM DOCTOR d CROSS JOIN FRANJA_HORARIA f CROSS JOIN ESPECIALIDAD e CROSS JOIN (SELECT LEVEL-1 n FROM DUAL CONNECT BY LEVEL<=15) dias
    WHERE d.numero_documento='99000001' AND f.estado='ACTIVO'
      AND e.nombre='TEST Medicina general'
      AND f.hora_inicio IN ('08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00')
      AND f.hora_fin=TO_CHAR(TO_DATE(f.hora_inicio,'HH24:MI')+1/24,'HH24:MI');
    DBMS_SESSION.CLEAR_IDENTIFIER;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Carga base TEST completada. Clave de prueba: KarelyTest2026!');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    DBMS_SESSION.CLEAR_IDENTIFIER;
    IF DBMS_LOB.ISTEMPORARY(v_blob)=1 THEN DBMS_LOB.FREETEMPORARY(v_blob); END IF;
    RAISE;
END;
/
